/**
 * @distilled.cloud/boxd -- boxd SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from boxd's public proto3 gRPC API.
 * `descriptors.ts` is written by convert too. Everything else in this folder
 * is hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Boxd from "@distilled.cloud/boxd";
 *
 * const program = Effect.gen(function* () {
 *   const { vmId } = yield* Boxd.createVm({ name: "my-machine" });
 *   const machine = yield* Boxd.getVm({ vmId });
 *   yield* Boxd.destroyVm({ vmId });
 *   return machine.status;
 * });
 *
 * program.pipe(
 *   Effect.provide(
 *     Layer.mergeAll(FetchHttpClient.layer, Boxd.CredentialsFromEnv, Boxd.BoxdProtocol),
 *   ),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { BoxdProtocol, type BoxdOpError, type BoxdOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/boxd.ts";
